const D = { energy: .58, scale: 1, density: .5, speed: 1, wear: .5, hue: 28, x: .5, y: .46, style: 'granite', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A crushed-stone / pea-gravel ground plane running away to the vanishing point.
// Not domed cobbles in fan courses (floor.cobblestone) and not a poured slab
// (floor.concrete): loose angular stones packed at random, each a little Worley cell
// that catches a raking light on its crown and drops its neighbour into grit-shadow.
// Only painted BELOW the horizon so the bg slot reads clean through above. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), wr = cl(P.wear,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', wet = sty==='wet', sep = sty==='sepia', ash = sty==='ash';

// ---- camera ----
const vy = cl(P.y,.18,.78)*height, vx = cl(P.x,.05,.95)*width;
const f = u*.92, H0 = 1;
const CS = .052*cl(P.scale,.35,2.6);        // stone cell size in world units

// ---- perpetual scroll toward the viewer (never re-phases; guarded on t0 reset) ----
if (S.z == null) S.z = 0;
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z += dt * P.speed * (.11 + .17*K.intensity) * (.55 + .6*en);
const zoff = S.z;

const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
// two broad light pools drifting on incommensurate rates — rake the stone crowns
const l1x = 1.5*Math.sin(tt*.083) + .7*Math.sin(tt*.197+1.3);
const l1z = 3.0 + 1.8*Math.sin(tt*.059+.7) + .9*Math.sin(tt*.151+2.1);
const l2x = -1.7*Math.sin(tt*.109+2.2) - .6*Math.sin(tt*.269);
const l2z = 5.2 + 2.4*Math.sin(tt*.047+1.9) + 1.1*Math.sin(tt*.179+.4);
const glow = (.40+.60*en)*(.55+.5*K.intensity) + bass*.26;

// ---- palette ----
let stoneD, stoneL, gritC, litC;
if (bp)        { stoneD=[212,74,13]; stoneL=[190,44,78]; gritC=[214,80,7];  litC=[186,52,92]; }
else if (wet)  { stoneD=[Hh+8,30,9];  stoneL=[Hh+4,16,52]; gritC=[Hh+10,36,6]; litC=[Hh-4,10,80]; }
else if (sep)  { stoneD=[32,30,20];  stoneL=[38,20,72];  gritC=[28,36,12];  litC=[40,15,84]; }
else if (ash)  { stoneD=[Hh,4,12];   stoneL=[Hh,3,50];   gritC=[Hh,6,7];    litC=[26,32,74]; }
else           { stoneD=[Hh,16,19];  stoneL=[Hh-6,10,74]; gritC=[Hh+4,22,10]; litC=[Hh-8,7,84]; }
const cSd = hsv(stoneD[0], stoneD[1]/100, stoneD[2]/100);
const cSl = hsv(stoneL[0], stoneL[1]/100, stoneL[2]/100);
const cGt = hsv(gritC[0], gritC[1]/100, gritC[2]/100);
const cLt = hsv(litC[0], litC[1]/100, litC[2]/100);

const BW = Math.max(360,Math.min(720,Math.round(width/2.4))), BH = Math.max(44, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const AL = P.alpha/100;
const j0 = Math.max(0, Math.floor((vy/height)*BH));
for (let j=0;j<j0;j++) for (let i=0;i<BW;i++) px[4*(j*BW+i)+3] = 0;

// Worley feature-point lookup in one cell (with strong jitter → irregular stone sizes)
function feat(cx,cz){ return [ (cx + .18 + .64*hsh(cx,cz)), (cz + .18 + .64*hsh(cx*3+7,cz*3+11)) ]; }

for (let j=j0;j<BH;j++){
  const sy = (j+.5)/BH*height, dy = sy - vy;
  if (dy < .35){ for (let i=0;i<BW;i++) px[4*(j*BW+i)+3] = 0; continue; }
  const Z = f*H0/dy, wz = Z + zoff;
  const far = cl((Z-1.1)/9, 0, 1);
  const det = cl(1 - far*1.05, .04, 1);
  const gcz = wz/CS;
  for (let i=0;i<BW;i++){
    const sx = (i+.5)/BW*width, X = (sx-vx)*Z/f;
    const o = 4*(j*BW+i);
    const gcx = X/CS;
    const bx = Math.floor(gcx), bz = Math.floor(gcz);
    // Worley F1/F2 over the 3x3 neighbourhood
    let f1=9, f2=9, bestX=0, bestZ=0, bestId=0;
    for (let oz=-1;oz<=1;oz++) for (let ox=-1;ox<=1;ox++){
      const cx=bx+ox, cz=bz+oz, ft=feat(cx,cz);
      const ddx=gcx-ft[0], ddz=gcz-ft[1], d=ddx*ddx+ddz*ddz;
      if (d<f1){ f2=f1; f1=d; bestX=ddx; bestZ=ddz; bestId=cx*92821+cz*53987; }
      else if (d<f2){ f2=d; }
    }
    const r1=Math.sqrt(f1), r2=Math.sqrt(f2);
    const q = hsh((bestId^0x9e37)&0xffff, (bestId>>>7)&0xffff);   // per-stone tone lottery
    // ---- mound: crown high at cell centre, shoulders fall to the grit ----
    const mound = cl(1 - r1/0.62, 0, 1);
    const nx = bestX/(r1+1e-3), nz = bestZ/(r1+1e-3);           // horizontal normal (outward)
    // ---- grit / sand shadow along the cell borders (F2-F1 small) ----
    const border = r2 - r1;
    const jw = .12 + wr*.10;
    const jt = cl(1 - border/jw, 0, 1);
    // ---- raking light from the two drifting pools ----
    const d1x=X-l1x, d1z=wz-zoff-l1z, d1=Math.sqrt(d1x*d1x+d1z*d1z);
    const d2x=X-l2x, d2z=wz-zoff-l2z, d2=Math.sqrt(d2x*d2x+d2z*d2z);
    const pool = Math.exp(-d1*d1*.11)*1.0 + Math.exp(-d2*d2*.075)*.72;
    const toLx=(l1x-X), toLz=(l1z-(wz-zoff)); const nl=Math.sqrt(toLx*toLx+toLz*toLz)+1e-3;
    const lamb = cl(.44 + (nx*(toLx/nl)+nz*(toLz/nl))*-.5 + mound*.5, 0, 1);
    let lum = (.30 + q*.40) * (.52 + lamb*.72) * (1 + pool*glow*.55);
    lum *= 1 - jt*.66;                                          // grit eats the light
    // stone grain + per-stone speckle so no facet is a flat fill
    const grain = fbm(X*70+bestId*.11, wz*70)*det + (1-det)*.5;
    lum *= .78 + grain*.42;
    lum += mound*pool*glow*.14;                                 // crown specular
    lum = cl(lum, 0, 1.5);
    let r = cSd[0]+(cSl[0]-cSd[0])*lum, g2 = cSd[1]+(cSl[1]-cSd[1])*lum, b2 = cSd[2]+(cSl[2]-cSd[2])*lum;
    r += (cGt[0]-r)*jt*.72; g2 += (cGt[1]-g2)*jt*.72; b2 += (cGt[2]-b2)*jt*.72;
    // warm specular tint on the brightest crowns
    const hot = cl((lum-1.02)*2.2,0,1)*(1-jt);
    r += (cLt[0]-r)*hot*.5; g2 += (cLt[1]-g2)*hot*.5; b2 += (cLt[2]-b2)*hot*.5;
    if (wet){
      const hollow = cl((jt*.7 + (1-mound)*.5 - .28)*1.7, 0, 1);
      const rip = .5+.5*Math.sin(wz*20 - tt*1.9 + X*6 + fbm(X*3, wz*3-tt*.4)*4.0);
      const spec = hollow*(.26+pool*glow*1.4)*(.55+rip*.7);
      r += (cLt[0]-r)*spec*.6; g2 += (cLt[1]-g2)*spec*.6; b2 += (cLt[2]-b2)*spec*.6;
    }
    if (bp){
      const on = jt > .40 ? 1 : 0;
      const v2 = .12+.10*(1-far);
      r = on? 74 : v2*40; g2 = on? 196*det+34 : v2*100; b2 = on? 244 : v2*172;
    }
    const hazeK = far*far*.85;
    const hc = bp? [40,120,190] : [cSl[0]*.70, cSl[1]*.70, cSl[2]*.76];
    r += (hc[0]-r)*hazeK; g2 += (hc[1]-g2)*hazeK; b2 += (hc[2]-b2)*hazeK;
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255);
    px[o+3] = 255*AL*cl(1-far*far*.72, 0, 1)*cl(dy/2.2, 0, 1);
  }
}
g.updatePixels();
push(); image(g,0,0,width,height); pop();

// ---- low dust drifting across the plane, crisp (buffer would alias it) ----
push();
blendMode(ADD);
noStroke();
const dens = cl(P.density,0,1);
const NM = Math.round(5 + dens*38);
for (let i=0;i<NM;i++){
  const f1 = hsh(i*13+7, 3), f2b = hsh(i*13+8, 5), f3 = hsh(i*13+9, 11);
  const mz = ((f2b + tt*(.018+f3*.06)*P.speed) % 1.05);
  const my = vy + Math.pow(mz,2.0)*(height-vy)*1.02;
  const mx = (f1 + Math.sin(tt*(.16+f3*.4)+f1*6.28)*.05)*width;
  const sz = u*(.0013+f3*.0045)*(.4+mz*1.7);
  fill(wet?Hh-4:Hh+18, bp?40:14, 100, (6+f3*11)*(.3+en)*(P.alpha/100)*(1-mz*.4));
  ellipse(mx, my, sz, sz*.7);
}
